mapper.select:
SELECT d.*
FROM sal_sed_order_detail d
INNER JOIN sal_sed_order o ON d.order_id = o.id
WHERE d.product_id = #{productId}
  AND d.match_id = #{matchId}
  AND d.sku_id = #{skuId}
  AND d.is_deleted = 0
  AND o.is_deleted = 0

SELECT DISTINCT d.order_id
FROM sal_sed_order_detail d
INNER JOIN sal_sed_order o ON d.order_id = o.id
WHERE d.product_id = #{productId}
  AND d.match_id = #{matchId}
  AND d.sku_id = #{skuId}
  AND d.is_deleted = 0
  AND o.is_deleted = 0
